ucs.falcon_logscale_query:
(#event_simpleName=FileWritten OR #event_simpleName=ProcessRollup2)
| case {
    #event_simpleName=FileWritten | TargetFileName=/\.(lockbit|HLJkNskOq)$/i OR TargetFileName=/(README|Restore-My-Files|HOW-TO-DECRYPT|LockBit_Ransomware)/i;
    #event_simpleName=ProcessRollup2 | ImageFileName=/(StealBit|PCHunter64|PCHunter32|ProcessHacker|GMER|dControl)\.exe$/i OR CommandLine=/(-pass\s|-gdel|-gmin|-gspd|vssadmin\s+delete\s+shadows|bcdedit.*recoveryenabled\s+No|wmic\s+shadowcopy\s+delete)/i;
  }
| groupBy([aid, ComputerName], function=[count(as=events), count(field=TargetFileName, distinct=true, as=unique_files), collect([ImageFileName, CommandLine, TargetFileName], multival=true, limit=20), min(@timestamp, as=first_seen), max(@timestamp, as=last_seen)])
| unique_files > 50 OR events > 5
| sort(first_seen, order=desc)
